function ingresso(lista, alvo) {
  let esquerda = 0;
  let direita = lista.length - 1;
  while (esquerda <= direita) {
    const meio = Math.floor((esquerda + direita) / 2);
    const atual = lista[meio];
    if (atual === alvo) return true;
    if (atual < alvo) esquerda = meio + 1;
    else direita = meio - 1;
  }
  return false;
}

